UPDATE t_workflow_action_run SET assignee_id = #{row.assigneeId}, status = #{row.status}, output_json = #{row.outputJson},
        submitted_by = #{row.submittedBy}, submitted_time = #{row.submittedTime}, version = version + 1,
        update_time = #{row.updateTime}
        WHERE action_run_id = #{row.actionRunId} AND version = #{row.version}
